(function(){
const rub=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number.isFinite(n)?n:0)+' ₽';
const num=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(Number.isFinite(n)?n:0);
const pct=n=>num(n)+'%';
const annuity=(amount,rate,months)=>{const r=rate/1200;if(!r)return amount/months;return amount*r*Math.pow(1+r,months)/(Math.pow(1+r,months)-1)};
const fv=(start,monthly,rate,months)=>{const r=rate/1200;return start*Math.pow(1+r,months)+(r?monthly*(Math.pow(1+r,months)-1)/r:monthly*months)};
const configs={
 mortgage:{title:'Ипотечный калькулятор',category:'Жильё',symbol:'⌂',lead:'Платёж, переплата и нагрузка на бюджет.',fields:[['price','Стоимость жилья','₽',7000000],['down','Первоначальный взнос','₽',1400000],['rate','Ставка','% годовых',6],['years','Срок','лет',25],['income','Доход семьи','₽ в месяц',180000]],calc:v=>{let a=Math.max(0,v.price-v.down),m=v.years*12,p=annuity(a,v.rate,m),total=p*m;return [p,[['Сумма кредита',rub(a)],['Переплата',rub(total-a)],['Всего банку',rub(total)],['Доля дохода',pct(p/v.income*100)]],`При этих условиях на ипотеку будет уходить около ${Math.round(p/v.income*100)}% указанного семейного дохода.`]}},
 'mortgage-early':{title:'Досрочное погашение ипотеки',category:'Жильё',symbol:'↘',lead:'Покажет, сколько процентов и времени можно сэкономить.',fields:[['amount','Остаток долга','₽',4800000],['rate','Ставка','% годовых',6],['years','Осталось платить','лет',22],['extra','Досрочно каждый месяц','₽',15000]],calc:v=>{let m=v.years*12,p=annuity(v.amount,v.rate,m),bal=v.amount,paid=0,n=0,r=v.rate/1200;while(bal>1&&n<1200){let interest=bal*r,principal=Math.min(bal,p-interest+v.extra);bal-=principal;paid+=interest+principal;n++}let base=p*m,save=Math.max(0,base-paid);return [p+v.extra,[['Новый срок',Math.ceil(n/12)+' лет '+n%12+' мес.'],['Экономия процентов',rub(save)],['Срок сократится',Math.max(0,m-n)+' мес.'],['Базовый платёж',rub(p)]],`Регулярные досрочные платежи могут сократить срок примерно на ${Math.max(0,m-n)} месяцев. Уточняйте дату списания и порядок пересчёта в своём банке.`]}},
 credit:{title:'Кредитный калькулятор',category:'Кредиты',symbol:'₽',lead:'Ежемесячный платёж и полная стоимость кредита.',fields:[['amount','Сумма кредита','₽',500000],['rate','Ставка','% годовых',22],['years','Срок','лет',3],['fees','Дополнительные расходы','₽',0]],calc:v=>{let m=v.years*12,p=annuity(v.amount,v.rate,m),total=p*m+v.fees;return [p,[['Переплата',rub(total-v.amount)],['Всего выплат',rub(total)],['Количество платежей',m],['Расходы и комиссии',rub(v.fees)]],`Каждый месяц потребуется около ${rub(p)}. До подписания договора сравните расчёт с ПСК в предложении банка.`]}},
 refinance:{title:'Калькулятор рефинансирования',category:'Кредиты',symbol:'⇄',lead:'Сравнит текущий кредит с новым предложением.',fields:[['balance','Остаток долга','₽',1200000],['oldRate','Текущая ставка','%',24],['newRate','Новая ставка','%',17],['years','Осталось платить','лет',4],['fees','Расходы на оформление','₽',15000]],calc:v=>{let m=v.years*12,o=annuity(v.balance,v.oldRate,m),n=annuity(v.balance,v.newRate,m),save=(o-n)*m-v.fees;return [n,[['Старый платёж',rub(o)],['Экономия в месяц',rub(o-n)],['Экономия всего',rub(save)],['Окупаемость расходов',Math.ceil(v.fees/Math.max(1,o-n))+' мес.']],save>0?'По заданным условиям рефинансирование потенциально выгодно. Проверьте страховку и комиссии.':'С учётом расходов новый кредит не даёт заметной экономии.']}},
 autoloan:{title:'Калькулятор автокредита',category:'Кредиты',symbol:'◇',lead:'Кредит, первоначальный взнос и реальная нагрузка.',fields:[['price','Цена автомобиля','₽',2200000],['down','Первоначальный взнос','₽',600000],['rate','Ставка','%',19],['years','Срок','лет',5],['insurance','Страхование и услуги','₽',120000]],calc:v=>{let a=v.price-v.down+v.insurance,m=v.years*12,p=annuity(a,v.rate,m),total=p*m+v.down;return [p,[['Сумма кредита',rub(a)],['Переплата',rub(total-v.price)],['Всего за автомобиль',rub(total)],['Первоначальный взнос',rub(v.down)]],`С учётом дополнительных услуг автомобиль обойдётся примерно в ${rub(total)}. Проверьте, можно ли отказаться от навязанных продуктов.`]}},
 deposit:{title:'Вклад и сложный процент',category:'Накопления',symbol:'%',lead:'Доход с пополнениями и капитализацией.',fields:[['start','Начальная сумма','₽',300000],['monthly','Пополнение в месяц','₽',20000],['rate','Ставка','% годовых',14],['years','Срок','лет',3]],calc:v=>{let m=v.years*12,end=fv(v.start,v.monthly,v.rate,m),own=v.start+v.monthly*m;return [end,[['Внесёте сами',rub(own)],['Процентный доход',rub(end-own)],['Срок',m+' мес.'],['Эффективный рост',pct((end/own-1)*100)]],`К концу срока сумма может вырасти до ${rub(end)}. Расчёт предполагает неизменную ставку и ежемесячную капитализацию.`]}},
 investment:{title:'Калькулятор инвестиций',category:'Накопления',symbol:'↗',lead:'Сценарий роста капитала с регулярными пополнениями.',fields:[['start','Стартовый капитал','₽',200000],['monthly','Ежемесячно','₽',15000],['rate','Ожидаемая доходность','% годовых',10],['years','Горизонт','лет',10],['inflation','Инфляция','%',6]],calc:v=>{let m=v.years*12,end=fv(v.start,v.monthly,v.rate,m),own=v.start+v.monthly*m,real=end/Math.pow(1+v.inflation/100,v.years);return [end,[['Вложения',rub(own)],['Потенциальный доход',rub(end-own)],['В сегодняшних деньгах',rub(real)],['Горизонт',v.years+' лет']],`Это сценарий, а не обещание доходности. При инфляции ${pct(v.inflation)} покупательная способность результата будет ближе к ${rub(real)}.`]}},
 bonds:{title:'Доходность облигаций',category:'Инвестиции',symbol:'▥',lead:'Купоны, цена покупки и ориентировочная доходность.',fields:[['price','Цена покупки','₽',950],['nominal','Номинал','₽',1000],['coupon','Купон за год','₽',120],['years','До погашения','лет',2],['tax','Налоговая ставка','%',13]],calc:v=>{let gross=v.coupon*v.years+(v.nominal-v.price),after=gross-v.coupon*v.years*v.tax/100,yieldp=(after/v.price/v.years)*100;return [pct(yieldp),[['Доход до налога',rub(gross)],['Доход после налога',rub(after)],['К погашению',rub(v.nominal)],['Купонов за период',rub(v.coupon*v.years)]],`Ориентировочная простая доходность после налога составляет ${pct(yieldp)} годовых. Для точной YTM нужны даты купонов и НКД.`]}},
 inflation:{title:'Инфляционный калькулятор',category:'Планирование',symbol:'≈',lead:'Покажет будущую цену и покупательную способность денег.',fields:[['amount','Сумма сегодня','₽',1000000],['rate','Инфляция','% в год',6],['years','Период','лет',10]],calc:v=>{let future=v.amount*Math.pow(1+v.rate/100,v.years),power=v.amount/Math.pow(1+v.rate/100,v.years);return [future,[['Будущая цена',rub(future)],['Покупательная способность',rub(power)],['Рост цен',pct((future/v.amount-1)*100)],['Период',v.years+' лет']],`Чтобы через ${v.years} лет купить то же, что сегодня стоит ${rub(v.amount)}, понадобится около ${rub(future)}.`]}},
 goal:{title:'Финансовая цель',category:'Планирование',symbol:'◎',lead:'Сколько откладывать, чтобы прийти к нужной сумме.',fields:[['target','Цель','₽',1500000],['start','Уже накоплено','₽',150000],['rate','Доходность','% годовых',8],['years','Срок','лет',5]],calc:v=>{let m=v.years*12,r=v.rate/1200,growth=v.start*Math.pow(1+r,m),need=Math.max(0,v.target-growth),monthly=r?need*r/(Math.pow(1+r,m)-1):need/m;return [monthly,[['Целевая сумма',rub(v.target)],['Стартовый капитал',rub(v.start)],['Срок',m+' мес.'],['Всего пополнений',rub(monthly*m)]],`Для достижения цели потребуется откладывать примерно ${rub(monthly)} ежемесячно. Лучше добавить запас 5–10%.`]}},
 'rent-vs-buy':{title:'Ипотека или аренда',category:'Жильё',symbol:'⌂?',lead:'Сравнит расходы двух сценариев на одном горизонте.',fields:[['price','Цена квартиры','₽',7000000],['down','Первоначальный взнос','₽',1400000],['rate','Ставка ипотеки','%',6],['rent','Аренда в месяц','₽',35000],['years','Горизонт сравнения','лет',10],['growth','Рост аренды','% в год',6]],calc:v=>{let loan=v.price-v.down,p=annuity(loan,v.rate,25*12),buy=v.down+p*v.years*12,rent=0;for(let y=0;y<v.years;y++)rent+=v.rent*12*Math.pow(1+v.growth/100,y);return [buy<rent?'Ипотека дешевле':'Аренда дешевле',[['Расходы на ипотеку',rub(buy)],['Расходы на аренду',rub(rent)],['Платёж по ипотеке',rub(p)],['Разница',rub(Math.abs(buy-rent))]],`На горизонте ${v.years} лет прямые платежи ниже в сценарии "${buy<rent?'ипотека':'аренда'}". Но для полного решения важны рост цены жилья, ремонт, налоги и доходность первоначального взноса.`]}},
 'credit-vs-invest':{title:'Погасить кредит или инвестировать',category:'Выбор',symbol:'⚖',lead:'Сопоставит гарантированную экономию и ожидаемую доходность.',fields:[['amount','Свободная сумма','₽',300000],['creditRate','Ставка кредита','%',24],['investRate','Ожидаемая доходность','%',12],['tax','Налог на доход','%',13],['years','Период','лет',3]],calc:v=>{let saving=v.amount*(Math.pow(1+v.creditRate/100,v.years)-1),gain=v.amount*(Math.pow(1+v.investRate/100,v.years)-1)*(1-v.tax/100),diff=saving-gain;return [diff>0?'Погашение сильнее':'Инвестиции потенциально выше',[['Экономия на процентах',rub(saving)],['Доход инвестиций',rub(gain)],['Разница',rub(Math.abs(diff))],['Риск',diff>0?'Ниже при погашении':'Доход не гарантирован']],`При заданных ставках финансовое преимущество у варианта "${diff>0?'погасить кредит':'инвестировать'}". Экономия процентов известна заранее, инвестиционная доходность — нет.`]}},
 ndfl:{title:'Калькулятор НДФЛ',category:'Налоги',symbol:'13',lead:'Сумма налога, доход до и после удержания.',fields:[['income','Доход','₽',120000],['rate','Ставка НДФЛ','%',13],['mode','Указанная сумма','select',0,[['0','до налога'],['1','на руки']]]],calc:v=>{let gross=v.mode==1?v.income/(1-v.rate/100):v.income,tax=gross*v.rate/100,net=gross-tax;return [tax,[['Доход до налога',rub(gross)],['На руки',rub(net)],['Ставка',pct(v.rate)],['За год при такой сумме',rub(tax*12)]],`Из дохода ${rub(gross)} налог составит примерно ${rub(tax)}, а после удержания останется ${rub(net)}.`]}},
 'tax-deduction':{title:'Налоговый вычет',category:'Налоги',symbol:'↩',lead:'Предварительная оценка возврата НДФЛ.',fields:[['expenses','Расходы для вычета','₽',300000],['limit','Лимит расходов','₽',400000],['paid','Уплачено НДФЛ','₽',80000],['rate','Ставка возврата','%',13]],calc:v=>{let base=Math.min(v.expenses,v.limit),refund=Math.min(v.paid,base*v.rate/100);return [refund,[['База вычета',rub(base)],['Расходы сверх лимита',rub(Math.max(0,v.expenses-v.limit))],['Уплачено НДФЛ',rub(v.paid)],['Неиспользованный НДФЛ',rub(Math.max(0,v.paid-refund))]],`Предварительно можно вернуть до ${rub(refund)}, но не больше фактически уплаченного НДФЛ и установленных законом лимитов.`]}},
 'property-tax':{title:'Налог с продажи квартиры',category:'Налоги',symbol:'⌂₽',lead:'Предварительно оценит налог с учётом вычета или расходов.',fields:[['sale','Цена продажи','₽',7500000],['purchase','Расходы на покупку','₽',6000000],['deduction','Фиксированный вычет','₽',1000000],['rate','Ставка налога','%',13],['years','Лет в собственности','лет',2]],calc:v=>{let base=Math.max(0,Math.min(v.sale-v.purchase,v.sale-v.deduction)),tax=base*v.rate/100;if(v.years>=5){base=0;tax=0}return [tax,[['Налоговая база',rub(base)],['Вычет по расходам',rub(v.purchase)],['Фиксированный вычет',rub(v.deduction)],['Срок владения',v.years+' лет']],tax?`Предварительный налог — ${rub(tax)}. Минимальный срок владения иногда составляет 3 года, поэтому проверьте основания приобретения.`:'По упрощённому условию калькулятора налог не возникает. Проверьте минимальный срок именно для вашей ситуации.']}},
 'self-employed':{title:'Калькулятор самозанятого',category:'Налоги',symbol:'НПД',lead:'НПД с доходов от физлиц и организаций.',fields:[['people','Доход от физлиц','₽ в месяц',60000],['business','Доход от организаций','₽ в месяц',40000],['bonus','Остаток бонуса','₽',10000]],calc:v=>{let regular=v.people*.04+v.business*.06,discount=Math.min(v.bonus,v.people*.01+v.business*.02),tax=Math.max(0,regular-discount);return [tax,[['Налог без бонуса',rub(regular)],['Использовано бонуса',rub(discount)],['Доход всего',rub(v.people+v.business)],['Эффективная ставка',pct(tax/(v.people+v.business)*100)]],`При указанных доходах НПД за месяц составит около ${rub(tax)}. Бонус уменьшает ставки временно, пока его остаток не исчерпан.`]}},
 'maternity-shares':{title:'Доли по материнскому капиталу',category:'Семья',symbol:'◫',lead:'Ориентир для распределения долей между членами семьи.',fields:[['price','Стоимость жилья','₽',6500000],['capital','Материнский капитал','₽',833000],['members','Членов семьи','человек',4]],calc:v=>{let minShare=v.capital/v.price/v.members*100,value=v.price*minShare/100;return [pct(minShare),[['Стоимость минимальной доли',rub(value)],['Доля маткапитала в жилье',pct(v.capital/v.price*100)],['Членов семьи',v.members],['Остаток стоимости',rub(v.price-v.capital)]],`Если распределять часть, оплаченную маткапиталом, поровну, ориентир на одного члена семьи — ${pct(minShare)}. Юридическое оформление согласуйте с нотариусом или Росреестром.`]}},
 vacation:{title:'Калькулятор отпускных',category:'Работа',symbol:'☼',lead:'Средний дневной заработок и сумма отпускных.',fields:[['salary','Начислено за 12 месяцев','₽',1200000],['months','Полностью отработано','месяцев',12],['days','Дней отпуска','дней',14],['tax','НДФЛ','%',13]],calc:v=>{let avg=v.salary/(29.3*v.months),gross=avg*v.days,net=gross*(1-v.tax/100);return [net,[['Начислено отпускных',rub(gross)],['Средний дневной',rub(avg)],['НДФЛ',rub(gross-net)],['Дней отпуска',v.days]],`Ориентировочно на руки получится ${rub(net)}. Неполные месяцы, больничные, премии и исключаемые периоды меняют точный расчёт.`]}},
 budget:{title:'Семейный бюджет',category:'Планирование',symbol:'▦',lead:'Покажет остаток, норму накоплений и долговую нагрузку.',fields:[['income','Доход семьи','₽ в месяц',200000],['essential','Обязательные расходы','₽',90000],['loans','Кредиты и ипотека','₽',40000],['wants','Остальные расходы','₽',40000],['goal','Цель накоплений','₽',30000]],calc:v=>{let free=v.income-v.essential-v.loans-v.wants,rate=free/v.income*100,debt=v.loans/v.income*100;return [free,[['Норма накоплений',pct(rate)],['Долговая нагрузка',pct(debt)],['Цель накоплений',rub(v.goal)],['Разница с целью',rub(free-v.goal)]],free>=v.goal?`После расходов остаётся ${rub(free)} — цель накоплений выполняется.`:`До цели не хватает ${rub(v.goal-free)}. Начните с пересмотра крупных повторяющихся расходов, а не мелочей.`]}}
};
function values(form){return Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)]))}
function render(type){let c=configs[type],root=document.querySelector('[data-calculator]');if(!c||!root)return;document.title=c.title+' — Fin AI Media';document.querySelector('[data-title]').textContent=c.title;document.querySelector('[data-lead]').textContent=c.lead;document.querySelector('[data-category]').textContent=c.category;document.querySelector('[data-symbol]').textContent=c.symbol;let form=root.querySelector('form');form.innerHTML='<div class="fields">'+c.fields.map(f=>{let [name,label,unit,val,opts]=f;if(unit==='select')return `<div class="calc-field"><label>${label}</label><select name="${name}">${opts.map(o=>`<option value="${o[0]}">${o[1]}</option>`).join('')}</select></div>`;return `<div class="calc-field"><label>${label}</label><input name="${name}" type="number" step="any" min="0" value="${val}"><small>${unit}</small></div>`}).join('')+'</div><button class="calc-run" type="submit">Рассчитать и объяснить</button>';
 const run=()=>{let [main,metrics,text]=c.calc(values(form));document.querySelector('[data-main]').textContent=typeof main==='number'?rub(main):main;document.querySelector('[data-metrics]').innerHTML=metrics.map(m=>`<div class="metric"><span>${m[0]}</span><b>${m[1]}</b></div>`).join('');document.querySelector('[data-explanation]').textContent=text};form.addEventListener('submit',e=>{e.preventDefault();run()});form.addEventListener('input',run);run()}
 const root=document.querySelector('[data-calculator]');if(root)render(root.dataset.calculator);
 document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');let f=b.dataset.filter;document.querySelectorAll('.calc-card').forEach(c=>c.hidden=f!=='all'&&c.dataset.category!==f)}));
})();
